"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["25588"],{62058(e){e.exports=JSON.parse('{"id":"F476","slug":"impermanent-loss","name":"Impermanent Loss for Liquidity Providers","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Decentralized finance (DeFi)","level":"Intermediate","aliases":["LP loss","DeFi liquidity providing","holding vs providing liquidity","price divergence loss"],"formula":{"latex":"IL=\\\\frac{2\\\\sqrt{r}}{1+r}-1,\\\\quad r=\\\\frac{P_{1}}{P_{0}}","also":[],"text":"If the price of token A relative to token B changes by a factor r, a liquidity provider\'s pool share is worth 2 x sqrt(r) / (1 + r) of what the same tokens would be worth if simply held, so Impermanent loss = 2 x sqrt(r) / (1 + r) - 1 (zero when r = 1, and the same for r and 1/r); Fees earned must exceed this loss for the pool to beat holding"},"symbols":[{"symbol":"r","meaning":"Ratio of the new price to the starting price","unit":"number"},{"symbol":"IL","meaning":"Value of the pool position compared with holding, minus 1","unit":"percent"}],"when_to_use":"Use it to see the cost to a liquidity provider when prices move. The pool sells the token that rises and buys the one that falls, so the provider ends up with less value than a holder. The loss is called impermanent because it disappears if the price returns, but it is real if the provider withdraws first.","worked_example":{"problem":"The price of token A doubles against token B. The pool earned 3% in fees over the same period.","inputs":{"r":2,"fees":3},"steps":[{"label":"Impermanent loss","working":"2 x sqrt(2) / (1+2)-1","value":"-5.72%"},{"label":"Pool value relative to holding","working":"1+-0.057191","value":"94.28%"},{"label":"Result vs holding after fees","working":"-0.057191+0.03","value":"-2.72%"},{"label":"Loss if the price falls to 1 / r","working":"2 x sqrt(1 / 2) / (1+1 / 2)-1","value":"-5.72%"}],"answer":"The impermanent loss is -5.72%. The position is worth 94.28% of a holder\'s value before fees. With fees of 3%, the result compared with holding is -2.72%. A fall to half the price gives the same loss, -5.72%."},"calculator":{"available":true,"inputs":[{"id":"r","label":"Price ratio (new / start)","unit":"","type":"number","default":2,"hint":""},{"id":"fees","label":"Fees earned (as a share of the position)","unit":"%","type":"number","default":3,"hint":""}],"checks":[{"expr":"r>0","message":"The price ratio must be above zero."}],"steps":[{"id":"il","label":"Impermanent loss","expr":"2*sqrt(r)/(1+r)-1","format":"pct2"},{"id":"rel","label":"Pool value relative to holding","expr":"1+il","format":"pct2"},{"id":"net","label":"Result vs holding after fees","expr":"il+fees","format":"pct2"},{"id":"il_half","label":"Loss if the price falls to 1 / r","expr":"2*sqrt(1/r)/(1+1/r)-1","format":"pct2"}],"results":["il","rel","net"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"il":-0.05719095841793653,"rel":0.9428090415820635,"net":-2.7190958417936534e-2,"il_half":-0.05719095841793653}},"finder":{"finds":"Whether fees pay for the loss from price moves","needs":"Price ratio and fees earned"},"related":[{"slug":"amm-constant-product-swap","name":"DeFi Automated Market Maker: Constant-Product Swap"},{"slug":"portfolio-variance-two-assets","name":"Risk of a Two-Asset Portfolio"},{"slug":"gas-fee-cost","name":"Ethereum Gas Fee Cost"}],"related_ids":["F475","F230","F473"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>I</mi><mi>L</mi><mo>=</mo><mfrac><mrow><mn>2</mn><msqrt><mi>r</mi></msqrt></mrow><mrow><mn>1</mn><mo>+</mo><mi>r</mi></mrow></mfrac><mo>\u2212</mo><mn>1</mn><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>r</mi><mo>=</mo><mfrac><msub><mi>P</mi><mn>1</mn></msub><msub><mi>P</mi><mn>0</mn></msub></mfrac></mrow><annotation encoding=\\"application/x-tex\\">IL=\\\\frac{2\\\\sqrt{r}}{1+r}-1,\\\\quad r=\\\\frac{P_{1}}{P_{0}}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"social-return-on-investment","name":"Impact Investing: Social Return on Investment"},"next":{"slug":"implementation-shortfall","name":"Implementation Shortfall and Market Impact"},"lesson":null,"total":522}')}}]);